# In-channel handoff
@alice: I'm IC. @bob you are ops lead on the DB.
@dave you own comms, status page update every 20 min.
All status questions go to @dave, not this thread.

# Envoy admission control style
if in_flight_requests > max_concurrency:
    return 503 'overloaded', Retry-After: 2
# prefer shedding low-priority traffic first
if priority == 'batch' and cpu_util > 0.85:
    return 429

try:
    recs = recommendation_client.get(user_id, timeout=0.2)
except (Timeout, ServiceUnavailable):
    recs = []   # render checkout without the block
render_checkout(cart, recs)

import random, time
base, cap = 0.1, 10
for attempt in range(5):
    try:
        return call()
    except Transient:
        sleep = random.uniform(0, min(cap, base * 2 ** attempt))  # full jitter
        time.sleep(sleep)

# Argo Rollouts canary steps
strategy:
  canary:
    steps:
    - setWeight: 5
    - pause: {duration: 10m}
    - analysis: {templates: [{templateName: error-rate}]}
    - setWeight: 50
    - pause: {duration: 10m}

// Go singleflight: N concurrent misses -> 1 DB query
v, err, _ := group.Do(key, func() (any, error) {
    v, err := db.Load(key)
    cache.Set(key, v, ttl + jitter())
    return v, err
})
